"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["7819"],{2935(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>a,contentTitle:()=>r,toc:()=>h,assets:()=>c});var o=JSON.parse('{"id":"how-to/cloud/firehose_howto","title":"How to use the Firehose Connector","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/cloud/firehose_howto.md","sourceDirName":"how-to/cloud","slug":"/how-to/cloud/firehose_howto","permalink":"/personal-av-docs/docs/how-to/cloud/firehose_howto","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/cloud/firehose_howto.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to use the Firehose Connector","sidebar_label":"How to use the Firehose Connector","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/howto/cloud/firehose_howto","format":"md"}}'),i=n(4848),s=n(8453);let a={title:"How to use the Firehose Connector",sidebar_label:"How to use the Firehose Connector",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/howto/cloud/firehose_howto",format:"md"},r,c={},h=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[":::note Edition\n",(0,i.jsx)(t.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(t.a,{href:"https://doc.airvantage.net/connectivity/howto/cloud/firehose_howto",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(t.p,{children:"How to use the Firehose Connector\nIntegrate and extend your AirVantage platform\nThis overview describes what you can do with the AirVantage Firehose Cloud Connector via a simple use case: Connecting your system to\nAWS Kinesis Firehose\nand accessing the raw data directly in the data store you specified (S3, redshift, Elasticsearch Service, etc.).\n1 /\nPrinciples\n2 /\nConfiguration\n3 /\nGet messages\nPrinciples\nThis section explains when and why to use this cloud connector, what it is, and the available options. To learn more about Kinesis Firehose see the\nAWS documentation web site\n.\nIntroduction\nThe Kinesis Firehose Cloud Connector provides the follow capabilities:\nMessage notifications from AirVantage\nTransform records with AWS Lambda\nRobust messaging for applications\nHigh-volume messaging\nDirect storage in a developer-selected destination: the developer just has to read data from the selected storage (i.e., no stream handling)\nParameters\nWhen you connect AirVantage to Kinesis Firehose Streams, you have to define the type of notifications you want: operations, data, alerts, or usages.\nConfiguration\nThis section explains how to configure your client to be robust, reliable, and secure. Please read this section carefully and provide the correct information to enable the end point on the AirVantage side.\nPrerequisites\nSet up an Amazon Web Services account\nhere\n.\nIntroduction\nThe\nrole\ndescribes the rights (called\npolicies\n) allowed for an AWS account on a specific object (here, a Kinesis Firehose).\nIn the schema on the right, we created an\nairvantageKinesisProducer\nrole applied to an AirVantage AWS account for a given company defined by the company\nuid\nin the\nSecretKey\n.\nAllowed policies\nare those which allow push messages in the stream and the last parameter defines the Kinesis Firehose to use.\nConfiguration Process\nStep 1.\nCreate\na Kinesis Firehose in the customer\u2019s AWS account, into which AirVantage will publish.\nThe\nsource\nmust be set to\nDirect Put\nto allow AirVantage to push data directly in a Firehose.\nBe careful! There is a charge for using Kinesis Firehose resources. So before creating your stream, calculate the number of shards you need according to the quantity of data you handle and\nestimate\nyour corresponding bill.\nWhen creating a Firehose, AWS creates a role called\nfirehose_delivery_role\nfor you. Don\u2019t use it with any external account:\nfirehose_delivery_role\ngives access to Redshift, S3, or ElasticSearch.\nStep 2.\nCreate\na Role in the customer\u2019s AWS account:\nThe\nRole\ntype must be\nCross-Account Access\n>\n3rd party AWS account\n.\nThe\nAccount ID\nmust be\n406826153012\n(Sierra\u2019s own AWS account ID).\nThe\nExternal ID\nmust be the UID of the customer\u2019s company in AirVantage.\nIn the role policy, click on\nNext\nand then\nFinish\n.\nEdit the role to add an\nInline policies\n: The role\u2019s\nPolicy\nshould only allow Sierra to write into the Firehose (firehose:PutRecord, firehose:PutRecordBatch).\nStep 3.\nSupply the following information using the\nCRM\nand select\nRequest Support\n:\nCustomer\u2019s AWS Account ID (a 12-digit number).\nName of the Role you created for AirVantage.\nCustomer\u2019s AWS Region ID (e.g.,\neu-west-1\n).\nName of the Firehose we should write into (not the full ARN).\nType of messages you want to receive:\nAlert event: Any alert rule triggered will be send\nOperation: Any operation state will be sent (creation, progress, success, or failed)\nUsages: any SIM usage\nNew message sent by the device: any device incoming communication\nOptionally, you can supply the data path to whitelist (only the values for this data will be sent in the data stream). To get the path for data, you can go to the timeline to view the data path in the tooltip as shown in the screenshot below:\nTest your setup\nYou can check that the data received from AirVantage shows up in the stream monitoring provided by Amazon. Use the\nPut Record Requests\ngraph to verify that your Firehose is connected to AirVantage. If no data is shown, you need to check your configuration.\nGet the messages\nTo get the data, refer to the AWS documentation corresponding to the destination storage you have selected:\nS3\nDocumentation\nRedshift\nDocumentation\nElasticSearch Service\nDocumentation"})]})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var o=n(6540);let i={},s=o.createContext(i);function a(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);